import json

metrics = [
    {"pod": "api-1", "cpu_percent": 42},
    {"pod": "api-2", "cpu_percent": 91},
    {"pod": "api-3", "cpu_percent": 55},
]

THRESHOLD = 80


def check_alerts(metrics, threshold):
    return [m["pod"] for m in metrics if m["cpu_percent"] > threshold]


def log_event(level, message, **fields):
    entry = {"level": level, "message": message}
    entry.update(fields)
    return json.dumps(entry, sort_keys=True)


firing = check_alerts(metrics, THRESHOLD)
print(f"alertas activas: {firing}")
for pod in firing:
    print(log_event("WARN", "cpu_above_threshold", pod=pod, threshold=THRESHOLD))
print(log_event("INFO", "check_complete", pods_checked=len(metrics)))
